// E30-E40 over the app transport (02-TRD §5; 04-UI-UX A16-A19). Every method returns the decoded wire body and throws LimsException on a non-2xx.
// Idempotency-Key (E33, E36, E38) is generated by the caller per review step / form and passed in; If-Match = `"<version>"` (02-CV §4.2). Nothing here logs or stores PHI (02-CV 9.2, REQ-SEC-103).
import 'package:lims_shared/lims_shared.dart';

import '../../core/api/api_client_factory.dart';

/// A fresh random-source key (uuidv7: unique per call, never derived from the booking content).
String newIdempotencyKey() => uuidv7();

abstract interface class PatientBookingsApi {
  /// E30: `{data:[BookableItem], page:{next_cursor?, limit}}`.
  Future<Object?> listBookableItems({
    required String bookingKind,
    String? query,
    String? cursor,
    int? limit,
  });

  /// E31: `{data:[BookingCentre]}`.
  Future<Object?> listBookingCentres({required String bookingKind});

  /// E32: `{data:[Slot]}`; dates 'yyyy-MM-dd'; [centreId] null for home_collection.
  Future<Object?> listSlots({
    required String bookingKind,
    String? centreId,
    required String dateFrom,
    required String dateTo,
  });

  /// E33 (also the reschedule): the created Booking.
  Future<Object?> createBooking({
    required Map<String, Object?> body,
    required String idempotencyKey,
  });

  /// E34: `{data:[Booking], page}`.
  Future<Object?> listBookings({String? status, String? cursor, int? limit});

  /// E35.
  Future<Object?> getBooking({required String bookingId});

  /// E36 (If-Match = [version]): the cancelled Booking.
  Future<Object?> cancelBooking({
    required String bookingId,
    required int version,
    required String idempotencyKey,
  });

  /// E37: `{data:[Address]}`.
  Future<Object?> listAddresses({String? profileId});

  /// E38: the created Address.
  Future<Object?> createAddress({
    required Map<String, Object?> body,
    required String idempotencyKey,
  });

  /// E39 (If-Match = [version]).
  Future<Object?> updateAddress({
    required String addressId,
    required int version,
    required Map<String, Object?> body,
  });

  /// E40 (If-Match = [version]) -> 204.
  Future<void> deactivateAddress({
    required String addressId,
    required int version,
  });
}

final _uuid = RegExp(
  r'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$',
);

/// A path is only ever built from a UUID; anything else is "not found" without a request.
String _id(String v) =>
    _uuid.hasMatch(v) ? v : throw LimsException(LimsErrorCodes.commonNotFound);

class TransportPatientBookingsApi implements PatientBookingsApi {
  TransportPatientBookingsApi({required PatientTransport transport})
    : _t = transport;

  final PatientTransport _t;
  static const _base = '/v1/engagement/me';

  @override
  Future<Object?> listBookableItems({
    required String bookingKind,
    String? query,
    String? cursor,
    int? limit,
  }) => _t(
    'GET',
    '$_base/bookable-items',
    query: {
      'booking_kind': bookingKind,
      if (query != null) 'query': query,
      if (cursor != null) 'cursor': cursor,
      if (limit != null) 'limit': limit,
    },
  );

  @override
  Future<Object?> listBookingCentres({required String bookingKind}) =>
      _t('GET', '$_base/booking-centres', query: {'booking_kind': bookingKind});

  @override
  Future<Object?> listSlots({
    required String bookingKind,
    String? centreId,
    required String dateFrom,
    required String dateTo,
  }) => _t(
    'GET',
    '$_base/slots',
    query: {
      'booking_kind': bookingKind,
      if (centreId != null) 'centre_id': centreId,
      'date_from': dateFrom,
      'date_to': dateTo,
    },
  );

  @override
  Future<Object?> createBooking({
    required Map<String, Object?> body,
    required String idempotencyKey,
  }) => _t(
    'POST',
    '$_base/bookings',
    headers: {'Idempotency-Key': idempotencyKey},
    body: body,
  );

  @override
  Future<Object?> listBookings({String? status, String? cursor, int? limit}) =>
      _t(
        'GET',
        '$_base/bookings',
        query: {
          if (status != null) 'status': status,
          if (cursor != null) 'cursor': cursor,
          if (limit != null) 'limit': limit,
        },
      );

  @override
  Future<Object?> getBooking({required String bookingId}) =>
      _t('GET', '$_base/bookings/${_id(bookingId)}');

  @override
  Future<Object?> cancelBooking({
    required String bookingId,
    required int version,
    required String idempotencyKey,
  }) => _t(
    'POST',
    '$_base/bookings/${_id(bookingId)}/cancel',
    headers: {'Idempotency-Key': idempotencyKey, 'If-Match': '"$version"'},
  );

  @override
  Future<Object?> listAddresses({String? profileId}) => _t(
    'GET',
    '$_base/addresses',
    query: {if (profileId != null) 'profile_id': profileId},
  );

  @override
  Future<Object?> createAddress({
    required Map<String, Object?> body,
    required String idempotencyKey,
  }) => _t(
    'POST',
    '$_base/addresses',
    headers: {'Idempotency-Key': idempotencyKey},
    body: body,
  );

  @override
  Future<Object?> updateAddress({
    required String addressId,
    required int version,
    required Map<String, Object?> body,
  }) => _t(
    'PUT',
    '$_base/addresses/${_id(addressId)}',
    headers: {'If-Match': '"$version"'},
    body: body,
  );

  @override
  Future<void> deactivateAddress({
    required String addressId,
    required int version,
  }) async {
    await _t(
      'POST',
      '$_base/addresses/${_id(addressId)}/deactivate',
      headers: {'If-Match': '"$version"'},
    );
  }
}
